-- AFROBACK Mobile — schéma Postgres pour le pilier Mythologie
-- Généré le 2026-08-05 à partir de
-- livrables/sites-web/afroback/app-mobile/data-model-mythologie.md
--
-- Contenu éditorial public (comme heros/decouverte_items) : lecture publique,
-- écriture réservée à service_role. image_url est renseigné pour les 5
-- mythes depuis le 2026-08-05 (photos retrouvées dans le dossier local
-- "AFROBACK CONTENT/Photos" de Yannick, à uploader manuellement dans le
-- bucket heroes-media/images/mythologie/ avant que ces URLs ne répondent
-- réellement). narration_audio_url reste NULL, aucune narration produite
-- à ce jour : l'app affiche un état "bientôt disponible" pour ce format.

create extension if not exists pgcrypto;

create table if not exists public.mythes (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  titre text not null,
  sous_titre text not null,
  peuple text not null,
  region text not null,
  zone text not null,
  epoque text not null,
  type_contenu text not null,
  theme text not null,
  recit_chapitres_fr jsonb not null default '[]',
  sources text[] not null default '{}',
  couleur text not null default '#E9BE77',
  image_url text,
  narration_audio_url text,
  ordre_affichage integer not null default 0,
  fichier_source text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.mythes enable row level security;

drop policy if exists "Public read access" on public.mythes;
create policy "Public read access" on public.mythes
  for select
  using (true);

-- Écriture réservée au rôle service_role (dashboard / futur back-office),
-- jamais au rôle anon utilisé par l'app mobile.

truncate table public.mythes;

insert into public.mythes (slug, titre, sous_titre, peuple, region, zone, epoque, type_contenu, theme, recit_chapitres_fr, sources, couleur, image_url, narration_audio_url, ordre_affichage, fichier_source) values (
  'mythe-miengu-esprits-eau-sawa',
  'Les Miengu, esprits des eaux du peuple Sawa',
  'Légende et tradition vivante des peuples côtiers du Cameroun (Duala, Bakweri, Malimba, Subu, Bakoko, Oroko), toujours pratiquée aujourd''hui.',
  'peuples Sawa du littoral camerounais (Duala, Bakweri, Malimba, Subu, Bakoko, Oroko)',
  'littoral et Sud-Ouest du Cameroun (estuaire du Wouri, côte atlantique)',
  'Littoral',
  'précolonial, croyance ancienne dont l''origine exacte n''est pas datable ; culte documenté comme établi dès le XIXe siècle malgré l''opposition missionnaire ; toujours vivant aujourd''hui',
  'légende / tradition orale, croyance toujours pratiquée aujourd''hui (pas un fait historique)',
  'esprit / génie de la nature, initiation, guérison',
  '[{"numero":1,"titre":"Origines : le monde sous les eaux","texte":"Écoute le bruit de l''océan qui vient mourir sur la côte camerounaise, là où le fleuve Wouri s''ouvre dans l''Atlantique. Écoute-le bien, car les Sawa, ceux qui depuis des générations vivent sur ce rivage, te diront que cette eau n''est jamais vide. Sous la surface, dans les rivières comme dans la mer, un peuple entier respire, un peuple qu''on ne voit qu''à de rares occasions et seulement si l''on est digne de le voir. On les appelle les miengu. Au singulier, un jengu. Chez les Bakweri, plus au sud, on dit liengu, et au pluriel maengu. Les noms changent d''un peuple sawa à l''autre, mais la croyance, elle, traverse toute la côte.\n\nLes vieux racontent qu''ils ressemblent à des êtres à mi-chemin entre l''humain et la sirène, la peau souvent très claire, les cheveux longs, la bouche marquée d''un bel écart entre les dents, ce que les Sawa considèrent depuis toujours comme un signe de beauté. Ils vivent dans les profondeurs, dans un royaume sous les eaux du Wouri et de l''océan, un royaume qu''on dit riche, ordonné, à l''image du monde des vivants mais inversé, plus lent, plus silencieux."},{"numero":2,"titre":"Les pouvoirs et le choix","texte":"Mais ne crois pas que les miengu se contentent de vivre cachés. Ils regardent ce qui se passe au-dessus d''eux, et ils choisissent. Ils choisissent qui, parmi les hommes et les femmes, mérite leur faveur. On dit qu''ils apportent quatre bienfaits à ceux qu''ils honorent : l''abondance de crevettes et de poissons dans les filets, la victoire dans les grandes courses de pirogues qui font la fierté des villages sawa, la protection contre la maladie et les épidémies, et la fin des pluies trop longues qui noient les récoltes. Un jengu peut aussi choisir un être humain, souvent une jeune fille, pour en faire son intermédiaire avec le monde visible : celle-là devient guérisseuse, initiée dans une société secrète dirigée par un maître de cérémonie qu''on appelle l''ekale, celui qui autrefois portait un masque pour parler au nom des esprits de l''eau. Chez les Bakweri, ce passage par le monde des liengu fait pleinement partie du rite qui mène une jeune fille vers l''âge adulte."},{"numero":3,"titre":"L''affrontement : résistance et mystère du plongeur","texte":"Il faut aussi dire, sans détour, que le monde des miengu n''a pas toujours été accueilli à bras ouverts. Quand les missionnaires européens sont arrivés sur cette côte, ils ont vu dans ce culte une chose à combattre, une croyance païenne à éradiquer. Les Sawa, eux, n''ont jamais cessé d''y croire, et le culte a continué de vivre, discrètement, tout au long du dix-neuvième siècle, documenté par les administrateurs et plus tard par les chercheurs venus étudier ces sociétés secrètes.\n\nEt chaque année, à Douala, cette croyance ancienne monte à la surface, littéralement, lors du grand festival du Ngondo. Depuis que cette fête a été relancée en 1949 comme un moment de rassemblement et de fierté du peuple sawa, elle a son sommet dans un rituel qui donne le frisson à tous ceux qui y assistent : un plongeur, choisi et préparé, se jette dans les eaux du Wouri avec une calebasse, et il y reste, disent les témoins, entre trois et dix minutes. Le temps s''étire, l''assistance retient son souffle, et quand il ressort enfin, on dit qu''il revient du royaume des miengu, porteur d''un message, d''une prophétie pour l''année qui commence. Personne ne sait exactement ce qui se passe sous l''eau pendant ces minutes-là. C''est précisément cela, le cœur du mystère sawa : une croyance qu''on ne peut ni prouver ni réfuter, mais qui continue, année après année, à réunir un peuple entier autour de son fleuve."},{"numero":4,"titre":"Héritage : une présence vivante aujourd''hui","texte":"Voilà ce que disent les Sawa depuis des générations, et ce qu''ils continuent de dire aujourd''hui, sans que le temps n''ait usé leur conviction. Les miengu ne sont pas un conte pour endormir les enfants. Pour beaucoup, sur cette côte, ils sont une présence réelle, respectée, qu''on honore avant de prendre la mer, qu''on invoque pour la santé, qu''on célèbre chaque année devant tout un peuple rassemblé. Si tu descends de cette terre où l''eau elle-même est habitée, souviens-toi que tes ancêtres n''ont jamais vu la nature comme un décor vide. Ils y ont vu un monde vivant, peuplé, avec lequel il fallait composer, dans le respect. Tiens-toi droit face à l''océan. Tu viens de là."}]'::jsonb,
  ARRAY['Wikipedia (anglais), article « Jengu », synthétisant notamment les travaux de l''anthropologue Edwin Ardener (1975) et de l''historien Ralph Austen (1992)', 'Wikipedia (anglais), article « Ngondo » (festival annuel de Douala)', 'Recherche croisée sur la description du culte, la société secrète de l''ekale et le rituel du plongeur, recoupée entre plusieurs synthèses encyclopédiques en ligne']::text[],
  '#E9BE77',
  'https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/mythologie/mythe-miengu-esprits-eau-sawa.jpg',
  null,
  0,
  'livrables/sites-web/afroback/Récits africains/mythe-miengu-esprits-eau-sawa.md'
);

insert into public.mythes (slug, titre, sous_titre, peuple, region, zone, epoque, type_contenu, theme, recit_chapitres_fr, sources, couleur, image_url, narration_audio_url, ordre_affichage, fichier_source) values (
  'mythe-nchare-yen-bamoun',
  'Nchare Yen, la course truquée qui fonda un royaume',
  'Légende fondatrice du royaume Bamoun, peuple Bamoun (Bamum), Ouest-Cameroun, fin du XIVe siècle.',
  'Bamoun (Bamum), d''origine tikar',
  'Ouest du Cameroun (Grassfields, région de Foumban)',
  'Ouest (Grassfields)',
  'précolonial, fin du XIVe et début du XVe siècle (règne traditionnellement daté de 1394 à 1418, parfois 1384 selon les sources)',
  'légende / tradition orale fondatrice, adossée à une chronologie que les historiens considèrent comme plausible mais non documentée par des écrits datés de l''époque',
  'figure fondatrice / légende royale',
  '[{"numero":1,"titre":"Rifum, trois héritiers pour un seul trône","texte":"Écoute. Vers la fin du quatorzième siècle, dans les hautes terres de l''Ouest du Cameroun, un peuple d''origine tikar vit encore uni sous l''autorité d''un même chef, à Rifum, non loin de l''actuel Mbankim. Mais les royaumes, comme les familles, ne restent pas toujours unis. Trois enfants de ce chef grandissent avec, chacun, l''idée qu''un jour le pouvoir pourrait leur revenir : deux frères, Nchare et Koumjouom, et leur sœur Mfom.\n\nKoumjouom est de ceux qu''on regarde d''emblée comme des rois. Grand, bâti pour la force, sûr de lui au point d''en être arrogant. Nchare, lui, est petit, mince, presque frêle à côté de son frère. Et pourtant, dans le cœur du peuple, c''est vers Nchare que les regards se tournent, car là où Koumjouom méprise, Nchare écoute. Là où l''un impose, l''autre partage. La modestie, dans ce monde-là comme dans beaucoup d''autres, pèse parfois plus lourd que la stature."},{"numero":2,"titre":"L''épreuve de la course se prépare","texte":"C''est ainsi, raconte la tradition bamoun, qu''il fut décidé de trancher la question du pouvoir par une épreuve simple, presque enfantine dans son principe : une course. Les trois prétendants s''assoient sur un même tronc d''arbre, à une centaine de mètres d''une pierre fixée au loin. Le premier qui pose le pied sur cette pierre devient roi. Koumjouom, athlétique, jubile déjà d''avance. Il sait la course gagnée avant même le signal de départ."},{"numero":3,"titre":"La course truquée","texte":"Mais dans l''ombre de cette compétition, quelqu''un veille pour Nchare. Un conseiller nommé Njimongha s''approche discrètement de Mfom avant le départ et lui glisse quelques mots. La jeune femme va s''asseoir sur le tronc, comme prévu, mais en s''installant, elle coince sous son poids un pan du pagne de son frère Koumjouom, sans que celui-ci s''en aperçoive. Quand vient le signal du départ, Koumjouom bondit et se retrouve retenu, freiné, comme si un obstacle invisible l''attachait au sol le temps de quelques secondes décisives. Ces secondes suffisent. Nchare s''élance, franchit la distance, et pose le premier pied sur la pierre. Les cris de victoire couvrent les protestations de Koumjouom, trop tard pour changer l''issue de la course. Nchare Yen est proclamé roi."},{"numero":4,"titre":"La naissance du royaume bamoun","texte":"De cette victoire naît un royaume. Nchare Yen, à la tête de deux à trois cents fidèles, franchit la rivière Mapé et s''installe dans la région où s''élève aujourd''hui Foumban. Il soumet sept principautés locales, dont le peuple pangié qui occupait alors le territoire de l''actuel Magba, et fixe sa première capitale à Njimom. Un pacte fondateur, transmis depuis par la tradition bamoun, scelle cette naissance en une formule simple : l''État bamoun est né, et Nchare en est le roi, avec succession assurée parmi ses fils. Sept conseillers kom, ceux-là mêmes qui l''avaient intronisé, deviennent les gardiens héréditaires de cette loi fondatrice.\n\nNchare Yen règne ainsi, selon la tradition, de 1394 à 1418, premier d''une lignée de souverains bamoun, les mfon, qui allait se prolonger pendant près de cinq siècles, jusqu''à ce que le royaume perde son indépendance à la fin du dix-neuvième siècle. Un descendant tardif de cette lignée, bien plus tard, deviendra l''un des souverains les plus célèbres d''Afrique centrale : le roi Njoya, inventeur d''une écriture propre à son peuple, déjà raconté ailleurs dans ce recueil. Mais tout commence ici, avec ce petit homme au ventre rond, disait-on, courageux malgré son apparence chétive, aimant la danse et le vin de palme, et dont la ruse, ou celle de ses partisans, valut plus que la force brute de son frère.\n\nIl faut le dire avec honnêteté : ce que nous savons de Nchare Yen nous vient presque entièrement de la tradition orale bamoun, transmise de génération en génération, puis consignée bien plus tard par les chroniqueurs du royaume et les historiens qui les ont étudiés. Aucun témoin de 1394 n''a laissé d''écrit daté de cette époque. C''est une histoire fondatrice, au sens plein du mot : elle fonde une identité, elle explique une légitimité, elle n''est pas un procès-verbal.\n\nRetiens ceci : les royaumes ne naissent pas toujours de la seule force des armes. Celui-ci naquit d''une ruse, d''une sœur qui choisit son camp, d''un petit homme préféré par son peuple à un géant orgueilleux. Si tu viens de cette terre de l''Ouest camerounais, souviens-toi que la grandeur ne se mesure jamais à la carrure. Tiens-toi droit. Tu viens de là."}]'::jsonb,
  ARRAY['Wikipedia (anglais et français), articles « Nchare Yen » et « Royaume bamoun »', 'Claude Tardits, *Le Royaume bamoum*, Paris, Peeters/Selaf, 1980 (étude académique de référence, doctorat d''État, université de Paris), citée via les synthèses encyclopédiques', 'royaumebamoun.com, portail officiel d''information du royaume bamoun, page consacrée à la légende de la course fondatrice', 'actualitte.com, présentation de l''ouvrage *Nchare Yen, le jeune prince tikar fondateur du royaume Bamoun* d''Aboubakar Mounpain']::text[],
  '#A0522D',
  'https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/mythologie/mythe-nchare-yen-bamoun.jpg',
  null,
  1,
  'livrables/sites-web/afroback/Récits africains/mythe-nchare-yen-bamoun.md'
);

insert into public.mythes (slug, titre, sous_titre, peuple, region, zone, epoque, type_contenu, theme, recit_chapitres_fr, sources, couleur, image_url, narration_audio_url, ordre_affichage, fichier_source) values (
  'mythe-ngan-medza-beti',
  'Ngan Medza, le serpent qui porta un peuple sur son dos',
  'Légende migratoire et fondatrice du peuple Beti-Fang (Ewondo, Eton, Bulu, Bene, Mvele, Manguissa, Ntumu), fleuve Sanaga, Centre-Cameroun.',
  'Beti-Fang (Ewondo, Eton, Bulu, Bene, Mvele, Manguissa, Ntumu, et par extension les Fang du Gabon et de Guinée équatoriale)',
  'Centre-Cameroun, fleuve Sanaga (migration depuis la région de l''Adamaoua vers le sud)',
  'Centre',
  'précolonial, migration généralement située entre le XVIIIe et le XIXe siècle',
  'légende / tradition orale migratoire et fondatrice (pas un fait historique vérifié)',
  'légende migratoire / figure fondatrice / esprit-animal protecteur',
  '[{"numero":1,"titre":"Nanga et les enfants de la savane (Origines)","texte":"Écoute. Il fut un temps où le peuple que l''on appelle aujourd''hui les Beti ne vivait pas dans la forêt profonde du Centre-Cameroun, mais bien plus au nord, du côté de l''Adamaoua. La tradition les fait tous descendre d''un même ancêtre, Nanga, un homme bantou que l''on décrit comme albinos, et de ses sept enfants : Kolo Beti, Eton Beti, Mvele Beti, Mvan Beti, Meka Beti, Bulu et Ntumu. De ces sept-là naîtront, au fil des générations, les grandes branches qui aujourd''hui encore se reconnaissent cousines : les Eton, les Ewondo, les Bene, les Bulu, les Manguissa, les Ntumu, et par-delà les frontières actuelles, les Fang du Gabon et de Guinée équatoriale."},{"numero":2,"titre":"La pression du nord et la fuite","texte":"Mais ce peuple ne resta pas éternellement dans ses terres du nord. La pression grandissait, disent les récits, venue de peuples musulmans peuls déterminés à imposer leur foi à tous les peuples animistes de la région. Beaucoup de traditions populaires rattachent cette pression au nom d''Ousman dan Fodio, chef peul et figure du grand jihad du début du dix-neuvième siècle. Il faut le dire honnêtement, ici comme partout où j''ouvre la bouche pour toi : les historiens s''accordent moins facilement sur ce point précis que la légende ne le laisse croire. Le mouvement de dan Fodio commence au tout début des années 1800, tandis que la migration des Beti vers le sud s''est probablement étalée sur une période plus longue, à travers plusieurs générations, entre le dix-huitième et le dix-neuvième siècle. Retiens l''idée juste, la pression des razzias et de l''islamisation venue du nord, mais garde la prudence sur le nom précis qu''on y accole."},{"numero":3,"titre":"Le pont vivant sur la Sanaga","texte":"Fuyant donc vers le sud, à travers une forêt dense et hostile, épuisés par des jours de marche, les Beti finissent par se heurter à un obstacle que rien ne semblait pouvoir franchir : le fleuve Sanaga, large, puissant, infranchissable pour un peuple entier chargé de ses enfants et de ses biens. C''est là, racontent les anciens, que Dieu, dans son amour pour ce peuple en fuite, leur envoya du secours sous une forme que nul n''attendait : un serpent gigantesque, mystique, nommé Ngan Medza. La créature s''allongea d''une rive à l''autre du fleuve, offrant son propre dos comme un pont vivant, et le peuple, famille après famille, commença la traversée.\n\nLa nuit tombait déjà. Celui qui portait la torche de bambou pour éclairer le passage se trouvait à l''arrière du groupe, et à mesure que la file avançait, la flamme faiblissait. Les récits divergent sur ce qui se produisit ensuite, et je ne te cacherai pas ce désaccord plutôt que de trancher à ta place : certains disent qu''un guerrier, dans l''obscurité, planta sa lance dans le dos du serpent, le prenant pour un tronc échoué ou cédant à une curiosité fatale ; d''autres racontent que c''est la flamme même de la torche qui tomba sur l''échine de Ngan Medza. Dans les deux versions, le résultat est le même : blessé, le serpent se cabra, versant dans les eaux ceux qui n''avaient pas encore achevé la traversée. Ceux qui purent se réfugier dans la forêt de l''autre rive y restèrent. C''est ainsi, dit la tradition, que le peuple beti se retrouva dispersé des deux côtés du fleuve Sanaga, comme il l''est resté jusqu''à aujourd''hui."},{"numero":4,"titre":"La mémoire du serpent (Héritage)","texte":"Ce serpent-là n''a jamais été oublié. On raconte qu''avant de disparaître dans les eaux, Ngan Medza donna aux siens des conseils pour vivre en harmonie avec la nature et les avertit des dangers à venir. Depuis, les sculpteurs beti taillent son image dans le bois, les chants traditionnels portent encore son nom, et certaines communautés célèbrent chaque année une fête en sa mémoire, Ngan Medza restant, bien plus qu''un simple animal du mythe, le symbole vivant du passage d''un peuple d''un monde ancien vers la terre qu''il habite encore.\n\nSi tu es Ewondo, Eton, Bulu, Bene ou Fang, ou si tu portes simplement en toi cette même mémoire de forêt et de fleuve, souviens-toi de ceci : ton peuple a traversé l''infranchissable. Il a été porté, un jour, par quelque chose de plus grand que lui, et il a payé cette traversée d''une perte, comme tout passage vers une terre nouvelle en coûte toujours une. Tiens-toi droit face à la Sanaga. Tu viens de là."}]'::jsonb,
  ARRAY['237online.com, « La fascinante légende Beti de Ngan Medza, le serpent mystique de la Sanaga »', 'camerounweb.com, « La traversée du fleuve Sanaga par le peuple Béti, mythe ou réalité ? »', 'akondanews.net, « La légende de la traversée de la Sanaga par le peuple Béti sur le dos d''un serpent »', 'Wikipedia (français), article « Beti (peuple) »']::text[],
  '#8B5A2B',
  'https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/mythologie/mythe-ngan-medza-beti.jpg',
  null,
  2,
  'livrables/sites-web/afroback/Récits africains/mythe-ngan-medza-beti.md'
);

insert into public.mythes (slug, titre, sous_titre, peuple, region, zone, epoque, type_contenu, theme, recit_chapitres_fr, sources, couleur, image_url, narration_audio_url, ordre_affichage, fichier_source) values (
  'mythe-ngog-lituba-bassa',
  'Ngog Lituba, le rocher percé, origine du peuple Bassa',
  'Mythe fondateur des peuples Bassa, Bakoko (Elog Mpo''o) et Bati, région de la Sanaga-Maritime, Cameroun.',
  'Bassa, Bakoko (Elog Mpo''o) et Bati',
  'Littoral (Sanaga-Maritime, commune de Nyanon, à 80 km d''Édéa, sur les rives de la Sanaga)',
  'Littoral',
  'précolonial, mythe d''origine dont la datation exacte n''est pas connue ; occupation attestée par la tradition entre le Xe et le XIIIe siècle avant migration vers le Wouri',
  'légende / tradition orale, mythe fondateur (pas un fait historique vérifié)',
  'mythe de création / figure fondatrice',
  '[{"numero":1,"titre":"Le rocher et la traque","texte":"Écoute. À quatre-vingts kilomètres d''Édéa, là où la forêt du Cameroun se referme sur elle-même et où la rivière Sanaga trace son chemin vers l''océan, il y a une montagne qui n''est pas tout à fait une montagne comme les autres. On l''appelle Ngog Lituba, ce qui veut dire, dans la langue des Bassa, le rocher percé. Une roche qui s''élève de la forêt jusqu''à mille cinq cents mètres, avec, à son flanc, une ouverture, une grotte, une bouche de pierre à huit cents mètres d''altitude. Et c''est de cette bouche-là, disent les Bassa, les Bakoko et les Bati depuis des générations, que leurs ancêtres sont sortis au monde."},{"numero":2,"titre":"La toile qui sauve un peuple","texte":"Voici ce que raconte la tradition. Il y a très longtemps, deux ancêtres fuyaient une persécution venue de très loin, d''une terre ancienne que certains récits nomment l''Égypte antique. Poursuivis, traqués, ils trouvent refuge dans le ventre de ce rocher, dans cette grotte cachée au cœur de la forêt. Et là, un miracle minuscule les sauve : une araignée, en une nuit, tisse sa toile en travers de l''entrée. Quand les poursuivants arrivent devant Ngog Lituba, ils voient cette toile intacte, immaculée, et ils se disent que personne n''a pu franchir cette ouverture depuis longtemps, qu''il n''y a là rien à trouver. Ils repartent. Le fil d''une simple araignée a suffi à sauver un peuple tout entier de l''extermination."},{"numero":3,"titre":"Les enfants du rocher percé","texte":"C''est de ce refuge, disent les anciens, que naissent les enfants du rocher percé, ceux que les Bassa appellent encore aujourd''hui Bon ba Ngok Lituba. De génération en génération, la population grandit dans et autour de cette grotte, jusqu''à ce que la terre elle-même ne suffise plus à la contenir. Alors, par vagues successives, les clans se dispersent depuis Ngog Lituba, essaiment à travers la forêt du Sud-Cameroun, et donnent naissance aux différents groupes qui aujourd''hui se reconnaissent comme cousins : les Bassa, les Bakoko qu''on appelle aussi Elog Mpo''o, et les Bati. Certaines traditions vont plus loin encore et voient dans Ngog Lituba non seulement le berceau de ces trois peuples, mais un lieu de repos pour les ancêtres de l''Afrique tout entière, la source première d''une fédération plus vaste que les récits anciens nomment la fédération de Nnanga.\n\nLa science, elle, regarde cette montagne autrement, sans contredire ni confirmer le mythe. Les géologues qui ont observé le rocher notent qu''il porte les traces d''une roche volcanique, gonflée par endroits comme si elle avait connu autrefois une chaleur extrême, et certains avancent l''hypothèse d''un ancien cratère, volcanique ou même météoritique, érodé par des millénaires de pluie et de vent. On raconte aussi que des empreintes de pas très anciennes se lisent encore dans la pierre, comme si le rocher lui-même gardait la mémoire de ceux qui l''ont un jour habité, entre le dixième et le treizième siècle, avant que ces populations ne migrent vers les rives du fleuve Wouri, plus au nord."},{"numero":4,"titre":"Un lieu sacré vivant","texte":"Ngog Lituba n''est pas un souvenir mort. C''est un lieu sacré vivant, un lieu de mémoire que les Bassa protègent jalousement. En 1959, quand un évêque a fait ériger sur le sommet une grande croix et une statue de la Vierge pour en faire un lieu de pèlerinage catholique, les communautés qui considèrent cette montagne comme sacrée s''en sont senties dépossédées, au point de porter cette blessure jusque devant les instances des Nations Unies, à Genève et à New York, en 2006, pour demander que soit reconnu le caractère sacré du site pour ses peuples d''origine. C''est dire à quel point cette histoire n''appartient pas au passé : elle continue de façonner l''identité et la dignité de tout un peuple aujourd''hui.\n\nSi tu es Bassa, Bakoko ou Bati, ou simplement si tu veux comprendre comment un peuple se raconte lui-même, retiens ceci : avant d''être une nation, avant d''être une langue, avant d''être un territoire, un peuple est d''abord une histoire qu''il se transmet sur ses propres origines. Et celle des enfants du rocher percé dit une chose simple et puissante : que même traqués, même acculés au fond d''une grotte, un peuple peut trouver refuge, survivre, et un jour se répandre à travers toute une forêt. Tiens-toi droit. Tu viens de là."}]'::jsonb,
  ARRAY['Wikipedia (français), article « Ngog Lituba »', 'WorldCat, référence académique : *Ngog-Lituba : mythe de l''origine de l''existence de l''homme Basaa du Sud-Cameroun, essai d''une anthropologie philosophique* (travail universitaire consacré spécifiquement à ce mythe)', 'eco-spirituality.org, « Ngog Lituba et l''origine des peuples Bassa Mpo''o et Bati »', 'savoirfairekang.com, « Ngog Lituba : Entre vérités et palabres »', 'Cameroon Tribune, « Ngog Lituba : Les mystères du rocher »']::text[],
  '#C99A5B',
