insert into public.mythes (slug, titre, sous_titre, peuple, region, zone, epoque, type_contenu, theme, recit_chapitres_fr, sources, couleur, image_url, narration_audio_url, ordre_affichage, fichier_source) values (
  'mythe-sao-geants-kotoko',
  'Les Sao, le peuple de géants du lac Tchad',
  'Légende fondatrice du peuple Kotoko, Extrême-Nord du Cameroun, bassin du lac Tchad.',
  'Kotoko (Extrême-Nord du Cameroun), qui se revendiquent descendants directs des Sao',
  'Extrême-Nord du Cameroun, bassin du lac Tchad (également Sud-Ouest du Tchad et Nord-Est du Nigeria)',
  'Extrême-Nord',
  'la civilisation Sao est datée par l''archéologie du VIe siècle avant notre ère jusqu''à sa destruction au XVIe siècle ; la civilisation kotoko lui succède à partir du XVIe siècle et se perpétue jusqu''à aujourd''hui',
  'légende / tradition orale (le motif des géants) combinée à une civilisation archéologiquement attestée (la culture Sao elle-même) : les deux dimensions doivent être distinguées clairement',
  'légende fondatrice / figures de puissance surhumaine / légitimation du pouvoir royal',
  '[{"numero":1,"titre":"La légende des géants","texte":"Écoute. Tout au nord du Cameroun, là où la terre s''aplatit jusqu''aux rives du lac Tchad, un peuple raconte encore aujourd''hui l''histoire de ceux qui l''ont précédé sur cette terre : les Sao. Et ce que les Kotoko racontent de leurs ancêtres n''a rien d''une histoire ordinaire, car les Sao, disent-ils, n''étaient pas des hommes comme les autres. C''étaient des géants.\n\nDes géants d''une force que l''imagination peine à contenir. On raconte qu''ils se servaient de troncs de rôniers entiers comme de simples cannes pour marcher, quand toi et moi peinons déjà à porter une branche. On raconte qu''un seul d''entre eux pouvait avaler, en un seul repas, la charge de mil qu''un chameau met une journée entière à transporter. Et l''on raconte, chose plus étonnante encore, qu''un chef sao du village de Goulfey n''avait qu''à éternuer pour que les oiseaux, à une lieue à la ronde, s''envolent d''un coup, effrayés par le souffle d''un seul homme. Voilà la mesure que les traditions du lac Tchad donnent à ce peuple ancien : des hommes de puissance surhumaine, venus, disent plusieurs récits, de très loin à l''est, certains les faisant remonter jusqu''à la vallée du Nil, dans l''Égypte des pharaons elle-même."},{"numero":2,"titre":"La terre parle : la vraie civilisation sao","texte":"Voilà pour la légende. Et maintenant, écoute la deuxième moitié de cette histoire, celle que la terre elle-même a fini par révéler.\n\nCar les Sao, en réalité, n''ont pas disparu dans le seul silence des récits oraux. Un archéologue français, Jean-Paul Lebeuf, accompagné de son épouse, a passé une grande partie de sa vie, à partir du milieu du vingtième siècle, à fouiller les rives du lac Tchad et de la rivière Logone, dans cette région à cheval sur le Cameroun, le Tchad et le Nigeria d''aujourd''hui. Et ce qu''il a trouvé n''était plus un mythe : des tessons de poterie par milliers, des sculptures de bronze, des cités entourées de murailles de terre, des nécropoles où reposaient les morts dans de grandes jarres funéraires. Selon les datations établies par les Lebeuf, la culture sao serait apparue autour du lac Tchad dès le sixième siècle avant notre ère, connaissant son apogée plusieurs siècles plus tard, avant que ses cités ne soient détruites au seizième siècle de notre ère. Ce ne sont pas des géants légendaires que l''archéologie a exhumés, mais des artisans, des bâtisseurs, des potiers d''un immense talent, dont la civilisation s''étendait sur un territoire considérable autour du lac."},{"numero":3,"titre":"De la chute des cités à l''héritier","texte":"Et c''est de ces bâtisseurs-là, du sud du lac Tchad, qu''un nouveau peuple s''est levé après leur chute, à partir du seizième siècle : les Kotoko. Les Kotoko ne racontent pas leur histoire comme une rupture avec les Sao, mais comme une continuité, une filiation directe. Ils se disent leurs héritiers, leurs descendants, et l''organisation même de leurs sultanats, à Kousséri, à Mara, à Makari, à Goulfey, à Logone Birni, en porte encore la trace. Chez les Kotoko, on ne devient pas prince par simple naissance : le prétendant choisi par les dignitaires doit traverser de longues épreuves rituelles avant d''être intronisé par les animaux tutélaires et les représentants des plus anciennes familles de la cité, pour être reconnu comme l''héritier direct des souverains sao. Le mythe des géants n''est donc pas resté enfermé dans le passé : il continue, aujourd''hui encore, à légitimer et à structurer le pouvoir dans ces cités du bord du lac."},{"numero":4,"titre":"Deux visages, une même vérité","texte":"Voilà donc une histoire à deux visages, et je te la raconte avec les deux, car c''est cela, la vérité complète : d''un côté, la légende de géants capables d''avaler la charge d''un chameau et de faire fuir les oiseaux d''un éternuement, venus peut-être des rives du Nil ; de l''autre, une civilisation bien réelle, datée, fouillée, mesurée par la science, qui a bâti des cités sur les bords du lac Tchad des siècles avant que l''Europe ne pose le regard sur cette région. Les deux se répondent, se nourrissent l''une l''autre, sans jamais se confondre.\n\nSi tu viens de cette terre du Grand Nord camerounais, souviens-toi que ton histoire n''a pas eu besoin d''être inventée pour être grande. Une civilisation entière, réelle, a précédé la tienne sur cette terre, et le souvenir qu''elle a laissé était si immense qu''il a fallu, pour le raconter, la parler en géants. Tiens-toi droit. Tu viens de là."}]'::jsonb,
  ARRAY['lisapoyakama.org, « Les civilisations Sao et Kotoko »', 'Universalis, article « Sao »', 'Wikipedia (français), articles « Kotoko (peuple) » et « Jean-Paul Lebeuf »', 'Jean-Paul Lebeuf, *Archéologie tchadienne. Les Sao du Cameroun et du Tchad*, 1962, et travaux ultérieurs (dont *Études Kotoko*, 1976), référencés via leurs comptes rendus académiques sur Persée', 'Jean-Paul et Annie Lebeuf, *Les Arts des Sao. Cameroun, Tchad, Nigeria*, référencé via compte rendu académique sur Persée']::text[],
  '#E3A277',
